"use client";

import { motion } from "framer-motion";
import { useSocket } from "@/contexts/SocketContext";
import ChatView from "./ChatView";

export default function ChatPanel() {

  const { room, name, connected, onlineUsers } = useSocket();

  if (!room) return null;

  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      className="flex flex-1 flex-col min-h-0 bg-[var(--background)]"
    >

      <header className="flex items-center justify-between border-b border-[var(--border)] bg-[var(--surface)] px-4 py-3">

        <div className="flex items-center gap-3">

          <div className="flex h-10 w-10 items-center justify-center rounded-full bg-[var(--muted)] text-sm font-medium text-[var(--muted-foreground)]">
            {room.slice(0, 2).toUpperCase()}
          </div>

          <div>
            <h2 className="text-sm font-semibold text-[var(--foreground)]">
              Group: {room}
            </h2>

            <p className="text-xs text-[var(--muted-foreground)]">
              {onlineUsers.length} users · {connected ? "Online" : "Connecting..."}
            </p>
          </div>

        </div>

      </header>

      <ChatView username={name} room={room} />

    </motion.div>
  );
}