"use client"

type Props = {
  room: string
  users: number
}

export default function ChatHeader({ room, users }: Props) {

  const startVideoCall = () => {
    alert("Video call feature placeholder")
  }

  return (

    <div className="flex items-center justify-between px-4 py-3 border-b border-gray-700 bg-gray-900">

      <div className="flex items-center gap-3">

        <div className="h-10 w-10 rounded-full bg-gray-700 flex items-center justify-center text-sm text-white">
          {room.slice(0,2).toUpperCase()}
        </div>

        <div>
          <div className="text-white font-medium">
            Group: {room}
          </div>

          <div className="text-xs text-gray-400">
            {users} users • Online
          </div>
        </div>

      </div>

      <button
        onClick={startVideoCall}
        className="p-2 rounded-md hover:bg-gray-800 transition text-lg"
      >
        📹
      </button>

    </div>

  )

}